   485→        public AcceptTxResult SubmitTx(Transaction tx, TxHandlingOptions handlingOptions)
   486→        {
   487→            bool startBroadcast = _txPoolConfig.PersistentBroadcastEnabled
   488→                                  && (handlingOptions & TxHandlingOptions.PersistentBroadcast) ==
   489→                                  TxHandlingOptions.PersistentBroadcast;
   490→
   491→            if (!AcceptTxWhenNotSynced &&
   492→                _headInfo.IsSyncing &&
   493→                // If local tx allow it to be accepted even when syncing
   494→                !startBroadcast)
   495→            {
   496→                return AcceptTxResult.Syncing;
   497→            }
   498→
   499→            Metrics.PendingTransactionsReceived++;
   500→
   501→            // assign a sequence number to transaction so we can order them by arrival times when
   502→            // gas prices are exactly the same
   503→            tx.PoolIndex = Interlocked.Increment(ref _txIndex);
   504→
   505→            NewDiscovered?.Invoke(this, new TxEventArgs(tx));
   506→
   507→            if (_logger.IsTrace)
   508→            {
   509→                TraceTx(tx, handlingOptions, startBroadcast);
   510→            }
   511→
   512→            TryConvertProofVersion(tx);
   513→
   514→            TxFilteringState state = new(tx, _accounts);
   515→            AcceptTxResult accepted;
   516→
   517→            _newHeadLock.EnterReadLock();
   518→            try
   519→            {
   520→                accepted = FilterTransactions(tx, handlingOptions, ref state);
   521→                if (accepted)
   522→                {
   523→                    accepted = AddCore(tx, ref state, startBroadcast);
   524→                }
   525→                else
   526→                {
   527→                    Metrics.PendingTransactionsDiscarded++;
   528→                }
   529→            }
   530→            finally
   531→            {
   532→                _newHeadLock.ExitReadLock();
   533→            }
   534→
   535→            if (accepted)
   536→            {
   537→                // Clear proper snapshot
   538→                if (tx.SupportsBlobs)
   539→                    _blobTransactionSnapshot = null;
   540→                else
   541→                    _transactionSnapshot = null;
   542→            }
   543→
   544→            return accepted;
   545→
   546→            [MethodImpl(MethodImplOptions.NoInlining)]
   547→            void TraceTx(Transaction tx, TxHandlingOptions handlingOptions, bool startBroadcast)
   548→            {
   549→                bool managedNonce = (handlingOptions & TxHandlingOptions.ManagedNonce) == TxHandlingOptions.ManagedNonce;
   550→                _logger.Trace($"Adding transaction {tx.ToString("  ")} - managed nonce: {managedNonce} | persistent broadcast {startBroadcast}");
   551→            }
   552→        }
   553→
   554→        private void TryConvertProofVersion(Transaction tx)
   555→        {
   556→            if (_txPoolConfig.ProofsTranslationEnabled
   557→                && tx is { SupportsBlobs: true, NetworkWrapper: ShardBlobNetworkWrapper { Version: ProofVersion.V0 } wrapper }
   558→                && _headInfo.CurrentProofVersion == ProofVersion.V1)
   559→            {
   560→                using ArrayPoolList<byte[]> cellProofs = new(Ckzg.CellsPerExtBlob * wrapper.Blobs.Length);
   561→
   562→                foreach (byte[] blob in wrapper.Blobs)
   563→                {
   564→                    using ArrayPoolSpan<byte> cellProofsOfOneBlob = new(Ckzg.CellsPerExtBlob * Ckzg.BytesPerProof);
   565→                    KzgPolynomialCommitments.ComputeCellProofs(blob, cellProofsOfOneBlob);
   566→                    byte[][] cellProofsSeparated = cellProofsOfOneBlob.Chunk(Ckzg.BytesPerProof).ToArray();
   567→                    cellProofs.AddRange(cellProofsSeparated);
   568→                }
   569→
   570→                tx.NetworkWrapper = wrapper with { Proofs = [.. cellProofs], Version = ProofVersion.V1 };
   571→            }
   572→        }
   573→
   574→        private AcceptTxResult FilterTransactions(Transaction tx, TxHandlingOptions handlingOptions, ref TxFilteringState state)
   575→        {
   576→            IIncomingTxFilter[] filters = _preHashFilters;
   577→            for (int i = 0; i < filters.Length; i++)
   578→            {
   579→                AcceptTxResult accepted = filters[i].Accept(tx, ref state, handlingOptions);
   580→
   581→                if (!accepted)
   582→                {
   583→                    tx.ClearPreHash();
   584→                    return accepted;
   585→                }
   586→            }
   587→
   588→            filters = _postHashFilters;
   589→            for (int i = 0; i < filters.Length; i++)
   590→            {
   591→                AcceptTxResult accepted = filters[i].Accept(tx, ref state, handlingOptions);
   592→
   593→                if (!accepted) return accepted;
   594→            }
   595→
   596→            return AcceptTxResult.Accepted;
   597→        }
   598→
   599→        private AcceptTxResult AddCore(Transaction tx, ref TxFilteringState state, bool isPersistentBroadcast)
   600→        {
   601→            bool eip1559Enabled = _specProvider.GetCurrentHeadSpec().IsEip1559Enabled;
   602→            UInt256 effectiveGasPrice = tx.CalculateEffectiveGasPrice(eip1559Enabled, _headInfo.CurrentBaseFee);
   603→            TxDistinctSortedPool relevantPool = (tx.SupportsBlobs ? _blobTransactions : _transactions);
   604→
   605→            relevantPool.TryGetBucketsWorstValue(tx.SenderAddress!, out Transaction? worstTx);
